import{describe,it,expect,beforeEach}from"vitest";import{VoiceConversationHistory,MAX_TURNS}from"../../frontend/js-modules/voice/voice-conversation-history.js";function fakeStorage(){const e=new Map;return{getItem:t=>e.has(t)?e.get(t):null,setItem:(t,o)=>e.set(t,o)}}describe("VoiceConversationHistory",()=>{let e,t;beforeEach(()=>{e=fakeStorage(),t=new VoiceConversationHistory({storage:e})}),it("starts empty",()=>{expect(t.getTurns()).toEqual([])}),it("appends a turn with defaults",()=>{t.append({speaker:"user",text:"hello"});const e=t.getTurns();expect(e).toHaveLength(1),expect(e[0].viaVoice).toBe(!1),expect(typeof e[0].timestamp).toBe("number")}),it("persists across instances sharing storage",()=>{t.append({speaker:"assistant",text:"hi there"});const o=new VoiceConversationHistory({storage:e});expect(o.getTurns()).toHaveLength(1)}),it("bounds the log to MAX_TURNS",()=>{for(let e=0;e<MAX_TURNS+5;e++)t.append({speaker:"user",text:`turn ${e}`});const e=t.getTurns();expect(e).toHaveLength(MAX_TURNS),expect(e[0].text).toBe("turn 5")}),it("clear empties the log",()=>{t.append({speaker:"user",text:"hello"}),t.clear(),expect(t.getTurns()).toEqual([])})});